import{_ as c,o as s,c as i,a3 as o,j as t,a as d,t as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Tenant API v1 — Email","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Email | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-email"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Email | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-email"}]]},"headers":[],"relativePath":"api/tenant-v1-email.md","filePath":"api/tenant-v1-email.md","lastUpdated":1786218247000}'),n={name:"api/tenant-v1-email.md"};function l(a,e,m,u,p,h){return s(),i("div",null,[e[8]||(e[8]=o('<h1 id="tenant-api-v1-—-email" tabindex="-1">Tenant API v1 — Email <a class="header-anchor" href="#tenant-api-v1-—-email" aria-label="Permalink to &quot;Tenant API v1 — Email&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:email</code>, plus Spatie permission middleware / policies.</p><p>Route parameters resolve account, folder, label, message, template, and signature models by <strong>uuid</strong>. Accounts, folders, labels, messages, and signatures are <strong>personal</strong> (authenticated user only via mailbox ownership). Templates may be <strong>shared</strong> (<code>is_shared</code>) for workspace-wide apply.</p><p>Personal mailbox traffic does <strong>not</strong> use <code>EmailConfigResolver</code> or Settings → Mail. OAuth is not available in v1.x (IMAP/SMTP credentials / app passwords only). Users may connect multiple accounts; compose requires <code>account_uuid</code> (SPA sends the mailbox chosen in From).</p><h2 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/email/accounts</code></td><td><code>email.view</code></td></tr><tr><td>POST</td><td><code>/email/accounts</code></td><td><code>email.accounts.manage</code></td></tr><tr><td>GET</td><td><code>/email/accounts/{uuid}</code></td><td><code>email.view</code> (own)</td></tr><tr><td>PUT</td><td><code>/email/accounts/{uuid}</code></td><td><code>email.accounts.manage</code></td></tr><tr><td>DELETE</td><td><code>/email/accounts/{uuid}</code></td><td><code>email.accounts.manage</code> (disconnect + purge local cache)</td></tr><tr><td>POST</td><td><code>/email/accounts/test</code></td><td><code>email.accounts.manage</code></td></tr><tr><td>POST</td><td><code>/email/accounts/{uuid}/sync</code></td><td><code>email.accounts.manage</code></td></tr><tr><td>POST</td><td><code>/email/accounts/{uuid}/default</code></td><td><code>email.accounts.manage</code></td></tr></tbody></table><p><code>POST /email/accounts</code> and <code>POST /email/accounts/test</code> accept IMAP + SMTP host/port/encryption/username/password, <code>email_address</code>, optional <code>from_name</code>, <code>is_default</code>, and optional <code>sync_interval_minutes</code> (<code>5</code> | <code>10</code> | <code>15</code> | <code>30</code> | <code>60</code>, default <code>5</code>). Passwords are stored with the Eloquent <code>encrypted</code> cast. Manual <code>POST …/sync</code> always queues a sync regardless of interval.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/email/accounts/{uuid}/folders</code></td><td><code>email.view</code> (own account)</td></tr><tr><td>GET</td><td><code>/email/folders/{uuid}</code></td><td><code>email.view</code> (own)</td></tr></tbody></table><p>Returns synced folders (<code>uuid</code>, <code>name</code>, <code>type</code>, <code>remote_path</code>, unread/total counts).</p><h2 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h2><p>EloSync-only tags per mailbox (not synced to IMAP). A message may have many labels while remaining in one folder.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/email/accounts/{uuid}/labels</code></td><td><code>email.view</code> (own account)</td></tr><tr><td>POST</td><td><code>/email/accounts/{uuid}/labels</code></td><td><code>email.update</code></td></tr><tr><td>GET</td><td><code>/email/labels/{uuid}</code></td><td><code>email.view</code> (own)</td></tr><tr><td>PUT</td><td><code>/email/labels/{uuid}</code></td><td><code>email.update</code></td></tr><tr><td>DELETE</td><td><code>/email/labels/{uuid}</code></td><td><code>email.update</code></td></tr><tr><td>GET</td><td><code>/email/labels/{uuid}/messages</code></td><td><code>email.view</code></td></tr><tr><td>PUT</td><td><code>/email/messages/{uuid}/labels</code></td><td><code>email.update</code></td></tr></tbody></table><p>Create/update body: <code>{ &quot;name&quot;: &quot;Follow up&quot;, &quot;color&quot;: &quot;#2563eb&quot;, &quot;sort_order&quot;: 1 }</code> (<code>color</code> optional <code>#RRGGBB</code>; <code>name</code> unique per mailbox).</p><p>Sync message labels: <code>{ &quot;label_uuids&quot;: [&quot;…&quot;] }</code> (replace set; empty array clears — field must be present). Label UUIDs must belong to the same mailbox as the message. Message list/show responses include <code>labels</code> when loaded.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/email/folders/{uuid}/messages</code></td><td><code>email.view</code></td></tr><tr><td>GET</td><td><code>/email/accounts/{uuid}/messages/search?q=</code></td><td><code>email.view</code></td></tr><tr><td>GET</td><td><code>/email/messages/{uuid}</code></td><td><code>email.view</code></td></tr><tr><td>POST</td><td><code>/email/messages/compose</code></td><td><code>email.create</code></td></tr><tr><td>PUT</td><td><code>/email/messages/{uuid}</code></td><td><code>email.update</code></td></tr><tr><td>PUT</td><td><code>/email/messages/{uuid}/labels</code></td><td><code>email.update</code></td></tr><tr><td>POST</td><td><code>/email/messages/{uuid}/send</code></td><td><code>email.update</code></td></tr><tr><td>DELETE</td><td><code>/email/messages/{uuid}</code></td><td><code>email.delete</code></td></tr><tr><td>POST</td><td><code>/email/messages/{uuid}/link</code></td><td><code>email.update</code></td></tr><tr><td>DELETE</td><td><code>/email/messages/{uuid}/link</code></td><td><code>email.update</code></td></tr></tbody></table><p>Compose body requires <code>account_uuid</code>, optional <code>to</code>/<code>cc</code>/<code>bcc</code> arrays, <code>subject</code>, <code>body_html</code> / <code>body_text</code>, and optional <code>in_reply_to</code> / <code>thread_key</code> for replies. Creates a draft; call <code>send</code> to queue <code>SendEmailMessageJob</code> on <code>email-sync</code>.</p><p>Update supports <code>is_read</code>, <code>is_starred</code>, <code>folder_uuid</code> (IMAP move to another folder on the same account), and draft field edits.</p><p><code>DELETE /email/messages/{uuid}</code> moves the message to the account <strong>Trash</strong> folder when present and the message is not already in Trash; otherwise permanently deletes (IMAP expunge + local row). Success message indicates which path ran.</p><p>Link body: <code>{ &quot;linkable_type&quot;: &quot;lead\\|contact\\|company\\|opportunity&quot;, &quot;linkable_id&quot;: 1 }</code>. Requires <code>email.update</code> on the message <strong>and</strong> authorization to <code>view</code> the target record (policy). There is no Email SPA linking UI in v1.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/email/templates</code></td><td>view / <code>email.templates.manage</code></td></tr><tr><td>GET/PUT/DELETE</td><td><code>/email/templates/{uuid}</code></td><td>view / manage (update/delete: creator or workspace owner)</td></tr><tr><td>POST</td><td><code>/email/templates/{uuid}/render</code></td><td><code>email.view</code> (own, shared, or owner)</td></tr></tbody></table><p>Create/update accept <code>name</code>, <code>category</code>, <code>subject</code>, <code>body_html</code>, optional <code>variables</code>, <code>is_active</code>, and <strong><code>is_shared</code></strong> (boolean; default <code>true</code> on create).</p><p>List query params:</p><ul><li><code>for_compose=1</code> — active templates the actor may <strong>apply</strong> (own <strong>or</strong> shared). Workspace owner does <strong>not</strong> receive others’ private templates in this mode.</li><li>Without <code>for_compose</code> — management list: own <strong>or</strong> shared; workspace owner sees all templates.</li><li>Optional filters: <code>search</code>, <code>category</code>, <code>is_active</code>, <code>is_shared</code>.</li></ul><p>Resource fields include <code>uuid</code>, <code>is_shared</code>, <code>user</code> <code>{ id, name, email }</code>, <code>can_edit</code>, <code>can_delete</code>. Apply/render always uses <code>uuid</code> (names are not unique across users).</p>',28)),t("p",null,[e[0]||(e[0]=d("Render body: ",-1)),e[1]||(e[1]=t("code",null,'{ "variables": { "name": "Ada" } }',-1)),e[2]||(e[2]=d(" → ",-1)),e[3]||(e[3]=t("code",null,"{ subject, body_html }",-1)),e[4]||(e[4]=d(" with ",-1)),t("code",null,r(a.placeholders),1),e[5]||(e[5]=d(" replaced. Inactive templates return ",-1)),e[6]||(e[6]=t("strong",null,"403",-1)),e[7]||(e[7]=d(" on render for viewers who cannot update them (creators / workspace owner may still render while editing).",-1))]),e[9]||(e[9]=o('<h2 id="signatures" tabindex="-1">Signatures <a class="header-anchor" href="#signatures" aria-label="Permalink to &quot;Signatures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/email/signatures</code></td><td>view / <code>email.signatures.manage</code></td></tr><tr><td>GET/PUT/DELETE</td><td><code>/email/signatures/{uuid}</code></td><td>view / manage</td></tr></tbody></table><h2 id="ops-notes" tabindex="-1">Ops notes <a class="header-anchor" href="#ops-notes" aria-label="Permalink to &quot;Ops notes&quot;">​</a></h2><ul><li>Queue workers: dedicated <code>email-sync</code> daemon (see <a href="/deployment/email#queue-worker-email-sync">deployment</a>); keep notifications on <code>emails,default</code></li><li>Scheduler: <code>email:sync</code> <strong>every minute</strong> — dispatches jobs only for mailboxes whose <code>sync_interval_minutes</code> (default 5) has elapsed</li><li>Production sync requires PHP <code>ext-imap</code></li><li>Platform transactional mail remains under Settings → Mail / Email Logs</li></ul>',4))])}const y=c(n,[["render",l]]);export{b as __pageData,y as default};
